cat > "$HOME/term-lab/m07/accion.sh" <<'BASH'
#!/usr/bin/env bash
case "${1:-}" in
  estado) printf 'Estado del ejemplo: preparado\n' ;;
  ayuda) printf 'Uso: accion.sh estado|ayuda\n' ;;
  *) printf 'Acción no admitida\n' >&2; exit 64 ;;
esac
BASH
bash -n "$HOME/term-lab/m07/accion.sh"
bash "$HOME/term-lab/m07/accion.sh" estado

cat > "$HOME/term-lab/m08/medir.sh" <<'BASH'
#!/usr/bin/env bash
set -u
ayuda() {
  printf 'Uso: medir.sh -f archivo [-m lineas|bytes] [-h]\n'
}
main() {
  local term_archivo='' term_modo='lineas' term_opcion
  local OPTIND=1
  while getopts ':f:m:h' term_opcion; do
    case "$term_opcion" in
      f) term_archivo=$OPTARG ;;
      m) term_modo=$OPTARG ;;
      h) ayuda; return 0 ;;
      :) printf 'Falta el valor de una opción\n' >&2; return 64 ;;
      \?) printf 'Opción no admitida\n' >&2; return 64 ;;
    esac
  done
  shift "$((OPTIND - 1))"
  if [[ $# -ne 0 || -z "$term_archivo" ]]; then
    ayuda >&2
    return 64
  fi
  case "$term_modo" in
    lineas|bytes) ;;
    *) printf 'Modo no admitido\n' >&2; return 64 ;;
  esac
  if [[ ! -f "$term_archivo" || ! -r "$term_archivo" ]]; then
    printf 'Se requiere un archivo regular legible\n' >&2
    return 66
  fi
  case "$term_modo" in
    lineas) wc -l < "$term_archivo" ;;
    bytes) wc -c < "$term_archivo" ;;
  esac
}
main "$@"
BASH
bash -n "$HOME/term-lab/m08/medir.sh"
